import javax.swing.*;import java.awt.*;import java.sql.SQLException;import java.util.*;
public class SettingsPanel extends JPanel{private final PayrollSettingsDAO dao=new PayrollSettingsDAO();private PayrollSettings settings;private final Map<String,JCheckBox> enabled=new LinkedHashMap<>();private final Map<String,JTextField> values=new LinkedHashMap<>();private final Map<String,JComboBox<String>> types=new LinkedHashMap<>();public SettingsPanel(PayrollSystemFrame d){setLayout(new BorderLayout());reload();}private void reload(){settings=dao.load();JPanel p=new JPanel(new GridBagLayout());GridBagConstraints g=new GridBagConstraints();g.insets=new Insets(5,8,5,8);g.fill=GridBagConstraints.HORIZONTAL;int r=0;for(Map.Entry<String,PayrollSettings.Component>x:settings.getComponents().entrySet()){JCheckBox c=new JCheckBox(x.getKey(),x.getValue().enabled);JTextField v=new JTextField(String.valueOf(x.getValue().value),10);JComboBox<String>t=new JComboBox<>(new String[]{"Percentage","Fixed Amount"});t.setSelectedIndex(x.getValue().percentage?0:1);enabled.put(x.getKey(),c);values.put(x.getKey(),v);types.put(x.getKey(),t);g.gridy=r;g.gridx=0;p.add(c,g);g.gridx=1;p.add(v,g);g.gridx=2;p.add(t,g);r++;}JPanel b=new JPanel();for(String n:new String[]{"Save Settings","Reset","Restore Default","Preview Salary Calculation"}){JButton z=new JButton(n);z.addActionListener(e->action(n));b.add(z);}add(new JScrollPane(p),BorderLayout.CENTER);add(b,BorderLayout.SOUTH);}private void action(String a){if(a.equals("Restore Default")){settings.defaults();removeAll();enabled.clear();values.clear();types.clear();reload();revalidate();return;}if(a.equals("Reset")){removeAll();enabled.clear();values.clear();types.clear();reload();revalidate();return;}for(String n:settings.getComponents().keySet()){PayrollSettings.Component c=settings.getComponents().get(n);c.enabled=enabled.get(n).isSelected();try{c.value=Double.parseDouble(values.get(n).getText());}catch(Exception e){c.value=0;}c.percentage=types.get(n).getSelectedIndex()==0;}if(a.startsWith("Preview")){PayrollCalculator.Result r=PayrollCalculator.calculate(50000,settings,0,0,0);JOptionPane.showMessageDialog(this,"For ₹50,000 basic salary:\nGross ₹"+r.gross+"\nNet ₹"+r.net);return;}try{dao.save(settings);JOptionPane.showMessageDialog(this,"Payroll settings saved.");}catch(SQLException e){JOptionPane.showMessageDialog(this,"Database error: "+e.getMessage());}}}
